
import { ref, reactive } from 'vue'
import { UploadList } from '@ADMIN/components/index'
import { ElMessage } from 'element-plus'

export default {
  components: {
    'upload-list': UploadList,
  },
  emits: ['handleCancel'],
  props: {
    visible: {
      type: Boolean,
      default: false,
    },
  },
  setup(props: any, ctx: any) {
    const rules = {
      name: {
        required: true,
        message: '请输入商品名称',
        trigger: 'blur',
      },
      price: {
        required: true,
        message: '请输入单价',
        trigger: 'blur',
      },
    }

    const form = reactive({
      name: '',
      price: '',
      desc: '',
      type: '短裤',
    })
    //编辑框确认
    const formRef = ref()
    const saveEdit = () => {
      if (!formRef.value) return
      formRef.value.validate((valid: any) => {
        if (valid) {
          ElMessage.success('提交成功！')
          ctx.emit('handleCancel', false)
        } else {
          console.log('error submit!')
          return false
        }
      })
    }
    const close = () => {
      ctx.emit('handleCancel', false)
    }
    //取消
    const handleCancel = () => {
      ctx.emit('handleCancel', false)
    }

    //选择上传图片回调
    const handleChang = (res: any) => {
      console.log(res)
    }

    return {
      form,
      rules,
      saveEdit,
      handleChang,
      handleCancel,
      formRef,
      props,
      close,
    }
  },
}
